class Solution:
    def countBreedStretches(self, pens: List[int], k: int) -> int:
        n, total = len(pens), 0
        for i in range(n):
            seen = set()
            for j in range(i, n):
                seen.add(pens[j])
                if len(seen) > k:
                    break
                if len(seen) == k:
                    total += 1
        return total

