class Solution {
    public long countBreedStretches(int[] pens, int k) {
        int n = pens.length;
        int[] mark = new int[n + 1];
        long total = 0;
        for (int i = 0; i < n; i++) {
            int distinct = 0;
            for (int j = i; j < n; j++) {
                if (mark[pens[j]] != i + 1) { mark[pens[j]] = i + 1; distinct++; }
                if (distinct > k) break;
                if (distinct == k) total++;
            }
        }
        return total;
    }
}

