class Solution:
    def countBreedStretches(self, pens: List[int], k: int) -> int:
        def at_most(limit):
            count = [0] * (len(pens) + 1)
            left = distinct = total = 0
            for i, v in enumerate(pens):
                count[v] += 1
                if count[v] == 1:
                    distinct += 1
                while distinct > limit:
                    count[pens[left]] -= 1
                    if count[pens[left]] == 0:
                        distinct -= 1
                    left += 1
                total += i - left + 1
            return total
        return at_most(k) - at_most(k - 1)

