class Solution {
    private long atMost(int[] pens, int limit) {
        int[] count = new int[pens.length + 1];
        int left = 0, distinct = 0;
        long total = 0;
        for (int i = 0; i < pens.length; i++) {
            if (count[pens[i]]++ == 0) distinct++;
            while (distinct > limit) if (--count[pens[left++]] == 0) distinct--;
            total += i - left + 1;
        }
        return total;
    }

    public long countBreedStretches(int[] pens, int k) {
        return atMost(pens, k) - atMost(pens, k - 1);
    }
}

