static long long at_most(const int* pens, int n, int limit) {
    int* count = calloc(n + 1, sizeof(int));
    int left = 0, distinct = 0;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        if (count[pens[i]]++ == 0) distinct++;
        while (distinct > limit) if (--count[pens[left++]] == 0) distinct--;
        total += i - left + 1;
    }
    free(count);
    return total;
}

long long countBreedStretches(int* pens, int pensSize, int k) {
